param (
    [Parameter(Mandatory=$true)]
    [string]$RepoName
)

# The cloud tests read the resource key from _51DEGREES_RESOURCE_KEY_BESPOKE,
# the organization variable common-ci puts into the environment under its own
# name before this runs. They fall back to a mocked HTTP client when it is
# not set.

# Include php.ini with the extension, generated by build-project, so that the
# on-premise tests run rather than skip for want of the native extension.
$sep = [IO.Path]::PathSeparator
if (Test-Path "$PWD/$RepoName/php.ini") {
    $env:PHP_INI_SCAN_DIR = "$sep$PWD/$RepoName"
}

./php/run-integration-tests.ps1 -RepoName $RepoName

exit $LASTEXITCODE
